import sys, optax
import jax.numpy as jnp
from jax import random
sys.path.append('storage/episteme')
from sota_fourier_ramp import SotaFourierRamp

def _define_hyperparameters():
    return {
        'learning_rate': 9e-4,
        'rank_k': 320,
        'proj_rank': 36,
        'hidden_size': 160,
        'drop': 0.05,
        'learn_gamma': True
    }

def compute_loss(predictions, targets, params, x):
    mae = jnp.mean(jnp.abs(predictions - targets))
    curv = predictions[:, 2:, :] - 2.0 * predictions[:, 1:-1, :] + predictions[:, :-2, :]
    return mae + 1e-4 * jnp.mean(curv * curv)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate)
    )

class ModelWrapper:
    def __init__(self, hparams):
        self.model = SotaFourierRamp(
            rank_k=hparams['rank_k'],
            proj_rank=hparams['proj_rank'],
            hidden_size=hparams['hidden_size'],
            drop=hparams['drop'],
            learn_gamma=hparams['learn_gamma']
        )
        self.needs_rng = True
    def init(self, rng_key, dummy_input):
        rng_params, rng_dropout = random.split(rng_key)
        return self.model.init({'params': rng_params, 'dropout': rng_dropout}, dummy_input, training=True)
    def apply(self, params, x, training=False, rngs=None):
        return self.model.apply(params, x, training=training, rngs=(rngs or {}))

def create_network(hparams):
    return ModelWrapper(hparams)
